sources=[]; cohorts=[]; assertions=[]
def source(n,title,pmc,year=U,doi=U,pmid=U,snapshot='search01.json',access='primary_source_search_excerpt',notes='Full article methods not independently inspected; no full-text review claimed.'):
    sources.append(dict(source_id=f'XCI-S{n:02}',title=title,authors=U,year=year,url=f'https://pmc.ncbi.nlm.nih.gov/articles/{pmc}/',doi=doi,pmid=pmid,source_type='primary_study',version=pmc+' repository record; version details unavailable',retrieved_at=DATE,access_level=access,snapshot_path=str(B/'snapshots'/snapshot),species='Homo sapiens',notes=notes))
def cohort(n,src,**kw):
    d={k:U for k in 'dataset_id accession participants ancestry tissue cell_type disease intervention sample_count donor_count parent_cohort notes'.split()}
    d.update(cohort_id=f'XCI-CO{n:02}',study_id=f'XCI-S{src:02}',dataset_id=f'XCI-D{n:02}',species='Homo sapiens',related_publications=[f'XCI-S{src:02}'],independence_status='unresolved');d.update(kw);cohorts.append(d)
fields='assertion_id subject subject_type predicate object object_type subject_layer object_layer measurement evidence_tier direction source_id cohort_id source_locator evidence_summary species ancestry age sex tissue disease disease_severity treatment_status cell_type cell_state developmental_state stimulation dose duration assay genomic_background time_point effect_size effect_unit uncertainty causal_directness limitations contradiction_group candidate_path qc_status qualitative_confidence'.split()
def a(n,src,co,sub,obj,pred,measurement,direction,summary,locator,hypothesis,**kw):
    d={k:U for k in fields}
    d.update(assertion_id=f'XCI-A{n:02}',source_id=f'XCI-S{src:02}',cohort_id=f'XCI-CO{co:02}',subject=sub,subject_type='protein',object=obj,object_type='protein',subject_layer='P',object_layer='P',predicate=pred,measurement=measurement,direction=direction,evidence_summary=summary,source_locator=locator,species='Homo sapiens',evidence_tier='P2',qc_status='needs_full_text',qualitative_confidence='low')
    d.update(kw)
    null=direction=='null'
    d['scoring_annotation']={'tested_hypothesis':hypothesis,'evidence_relation':'inconclusive' if null else 'supports','null_adequacy':'No equivalence bound, confidence interval or justified absence threshold available; not adequate to support relationship absence.' if null else 'not_applicable','rationale':('Qualitative nondetection is retained as an observation, not evidence of an absent relationship.' if null else 'The recorded contrast supports this narrow hypothesis in the assayed context only.')+' Pending independent review; needs_full_text records remain ineligible for default prior scoring.'}
    assertions.append(d)

