# Every returned search candidate is logged, not only the selected papers.
screen=[]
included={s['url'].rstrip('/'):s for s in sources}
for q in [1,2,3]:
    payload=json.loads((B/'snapshots'/f'search{q:02}.json').read_text())['response']
    for block in payload.split('--------------------------------------------------------------------------------'):
        first=block.strip().splitlines()[0] if block.strip() else ''
        m=re.match(r'(.+) \((https?://[^\s]+)\)$',first)
        if not m:continue
        title,url=m.groups(); normalized=url.split('?')[0].rstrip('/')
        s=included.get(normalized)
        if s is None:
            s=next((z for z in sources if z['pmid']!=U and f'pubmed.ncbi.nlm.nih.gov/{z["pmid"]}' in normalized),None)
        if s is None:
            s=next((z for z in sources if title.casefold().strip()==z['title'].casefold().strip()),None)
        if s:
            decision='include'
            reason='Relevant primary human result selected;full Methods and Results subsequently inspected in Chrome. Duplicate repository or PubMed records map to the same source.'
        else:
            decision='exclude'
            if any(x in title.lower() for x in ['review','survival and apoptosis in health','interleukin 1-alpha','siglec8']):reason='Review/general reference; not used as a primary perturbation assertion.'
            elif any(x in title.lower() for x in ['endothelin','dapsone','two-step adhesion','shear stress','neutralization of il-8']):reason='Different perturbation or unresolved IL1 species; outside this bounded extraction.'
            else:reason='Potentially relevant primary or secondary candidate not selected after stronger accessible targeted results; full source not inspected in this bounded pass.'
        screen.append(dict(candidate_id=f'XCI-C{len(screen)+1:03}',query_id=f'XCI-Q{(5 if q==3 else q):02}',title=title,url=normalized,doi=s['doi'] if s else U,pmid=s['pmid'] if s else U,decision=decision,reason=reason,source_id=s['source_id'] if s else U))
(B/'screening.json').write_text(json.dumps({'scope':'All candidates returned in three saved search batches that expose a title/URL header; no exhaustive-search claim. No reference-list citation chaining performed. URL query metadata omitted. Primary full-method closure documented as XCI-Q07.','candidates':screen},indent=2,ensure_ascii=False)+'\n')
for row in assertions:
    assert all(k in row for k in fields)
    assert all(v is not None and v!='' for v in row.values())
assert len({x['assertion_id'] for x in assertions})==len(assertions)
assert all(Path(s['snapshot_path']).exists() for s in sources)
assert all(a['source_id'] in {s['source_id'] for s in sources} and a['cohort_id'] in {c['cohort_id'] for c in cohorts} for a in assertions)
assert all(a['scoring_annotation']['evidence_relation']=='inconclusive' for a in assertions if a['direction']=='null')
